parameters.jsCode:
const item = $input.first().json;
const analisis = JSON.parse(item.choices[0].message.content);

const s = Math.max(
  0,
  Math.min(100, Math.trunc(Number(analisis.score)))
);

analisis.score = s;

analisis.clasificacion =
  s >= 80 ? 'REVISION_PRIORITARIA' :
  s >= 60 ? 'REVISION_MANUAL' :
            'REVISION_SECUNDARIA';

analisis.estado =
  s >= 80 ? 'PENDIENTE_REVISION' : 'ANALIZADO';

return [{ json: analisis }];

const filas = $input.all();
const form = $('Webhook').item.json.body || $('Webhook').item.json;

const existe = filas.some(f =>
  f.json.correo === form.correo && f.json.vacante === form.vacante
);

// Pasamos adelante el dato del duplicado
return [{ json: { duplicado: existe } }];

