const filas = $input.all().filter(f => f.json.id); // ignora el item vacío si no hay pendientes

let mensaje;
if (filas.length === 0) {
  mensaje = '✅ No hay candidatos pendientes de revisión. ¡Todo al día!';
} else {
  mensaje = `📋 CANDIDATOS PENDIENTES DE REVISIÓN (${filas.length})\n\n`;
  filas.forEach((f, i) => {
    mensaje += `${i + 1}. ${f.json.id} — ${f.json.nombre} — ${f.json.vacante} — ${f.json.score}/100\n`;
  });
  mensaje += `\nUsa /candidato <ID> para ver el detalle.`;
}

return [{ json: { mensaje } }];

const item = $input.first();
const body = item.json.body || item.json;
const binary = item.binary || {};
const cv = binary.cv;

const errores = [];

function estaVacio(valor) {
  return valor === undefined ||
    valor === null ||
    String(valor).trim() === '';
}

// Campos obligatorios
const camposObligatorios = [
  'nombre',
  'correo',
  'telefono',
  'vacante',
  'experiencia',
  'tecnologias'
];

for (const campo of camposObligatorios) {
  if (estaVacio(body[campo])) {
    errores.push(`Falta el campo obligatorio: ${campo}`);
  }
}

// Validación básica del correo
if (
  !estaVacio(body.correo) &&
  !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(body.correo).trim())
) {
  errores.push('El correo electrónico no tiene un formato válido');
}

// La experiencia no puede ser negativa
if (
  !estaVacio(body.experiencia) &&
  Number(body.experiencia) < 0
) {
  errores.push('La experiencia no puede ser negativa');
}

// Busca el consentimiento con varios nombres posibles
const consentimiento =
  body.tratamiento_datos ??
  body.consentimiento ??
  body.acepta_datos ??
  body.aceptar_datos ??
  body.autorizacion_datos;

const consentimientoNormalizado = String(
  consentimiento ?? ''
).toLowerCase().trim();

const valoresAceptados = [
  'true',
  'on',
  '1',
  'si',
  'sí',
  'acepto',
  'accepted'
];

if (!valoresAceptados.includes(consentimientoNormalizado)) {
  errores.push(
    'El candidato debe aceptar el tratamiento de datos personales'
  );
}

// Validación del archivo
if (!cv) {
  errores.push('No se recibió la hoja de vida');
} else {
  const nombreArchivo = String(cv.fileName || '').toLowerCase();
  const tipoArchivo = String(cv.mimeType || '').toLowerCase();

  const extensionPdf = nombreArchivo.endsWith('.pdf');
  const mimePdf = tipoArchivo === 'application/pdf';
  const extensionesImagen = ['.jpg', '.jpeg', '.png', '.webp'];
  const extensionImagen = extensionesImagen.some(ext => nombreArchivo.endsWith(ext));
  const mimeImagen = tipoArchivo.startsWith('image/');

  const esPdfValido = extensionPdf && mimePdf;
  const esImagenValida = extensionImagen && mimeImagen;

  if (!esPdfValido && !esImagenValida) {
    errores.push('La hoja de vida debe ser un PDF o una imagen JPG, PNG o WEBP válida');
  }
}

return [
  {
    json: {
      ...item.json,
      validacion_ok: errores.length === 0,
      errores
    },
    binary
  }
];

const item = $input.first().json;
// Puede venir del Extract (campo text) o del export de Drive (texto plano)
let texto = item.text || item.data || (typeof item === 'string' ? item : '') || '';
return [{ json: { texto_cv: texto } }];

// Re-adjunta el archivo original del Webhook (Extract from File lo eliminó)
const wh = $('Webhook').first();
return [{ json: {}, binary: wh.binary }];

const entrada = $input.first().json;

const vacante = String(
  $('Webhook').item.json.body.vacante || ''
).trim();

// Normaliza mayúsculas y tildes para reconocer mejor las vacantes.
const clave = vacante
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .trim();

let requisitos;

if (
  clave.includes('backend') ||
  clave.includes('desarrollador') ||
  clave.includes('programador')
) {
  requisitos = {
    tecnologias: [
      'Java',
      'Spring Boot',
      'SQL',
      'Git',
      'REST API',
      'Docker'
    ],
    experiencia_minima: 1,
    formacion:
      'Técnica, tecnológica o profesional en desarrollo de software, sistemas o áreas relacionadas',
    descripcion:
      'Desarrollo y mantenimiento de aplicaciones backend, servicios web y bases de datos',
    responsabilidades: [
      'Desarrollar servicios y API REST',
      'Trabajar con bases de datos relacionales',
      'Utilizar control de versiones con Git',
      'Realizar pruebas y corrección de errores'
    ]
  };

} else if (
  clave.includes('analista') ||
  clave.includes('datos') ||
  clave.includes('data')
) {
  requisitos = {
    tecnologias: [
      'SQL',
      'Python',
      'Power BI',
      'Excel',
      'ETL',
      'Visualización de datos'
    ],
    experiencia_minima: 1,
    formacion:
      'Técnica, tecnológica o profesional en sistemas, estadística, ingeniería o áreas relacionadas',
    descripcion:
      'Análisis, limpieza, transformación y visualización de información para apoyar decisiones',
    responsabilidades: [
      'Consultar y transformar datos',
      'Construir reportes y dashboards',
      'Identificar tendencias e indicadores',
      'Validar la calidad de los datos'
    ]
  };

} else if (
  clave.includes('disenador') ||
  clave.includes('diseno') ||
  clave.includes('ux') ||
  clave.includes('ui')
) {
  requisitos = {
    tecnologias: [
      'Figma',
      'Prototipado',
      'Wireframes',
      'Investigación de usuarios',
      'Design Systems',
      'Diseño responsive'
    ],
    experiencia_minima: 1,
    formacion:
      'Técnica, tecnológica o profesional en diseño gráfico, diseño digital, UX/UI o áreas relacionadas',
    descripcion:
      'Diseño de experiencias de usuario e interfaces digitales claras, accesibles y consistentes',
    responsabilidades: [
      'Crear wireframes y prototipos',
      'Diseñar interfaces digitales',
      'Realizar investigación de usuarios',
      'Mantener componentes y sistemas de diseño'
    ]
  };

} else if (
  clave.includes('soporte') ||
  clave.includes('mesa de ayuda') ||
  clave.includes('help desk') ||
  clave.includes('tecnico de sistemas')
) {
  requisitos = {
    tecnologias: [
      'Windows',
      'Linux',
      'Redes TCP/IP',
      'Soporte de hardware y software',
      'Sistemas de tickets',
      'Microsoft 365'
    ],
    experiencia_minima: 1,
    formacion:
      'Técnica o tecnológica en sistemas, informática, redes o áreas relacionadas',
    descripcion:
      'Atención de incidentes, soporte a usuarios, mantenimiento de equipos y solución de problemas técnicos',
    responsabilidades: [
      'Atender solicitudes e incidentes de usuarios',
      'Diagnosticar problemas de hardware y software',
      'Configurar equipos y aplicaciones',
      'Registrar y dar seguimiento a tickets'
    ]
  };

} else {
  requisitos = {
    tecnologias: [],
    experiencia_minima: 0,
    formacion: 'No especificada',
    descripcion: 'Vacante sin requisitos configurados',
    responsabilidades: [],
    requiere_revision_manual: true
  };
}

return [
  {
    json: {
      ...entrada,
      vacante,
      requisitos
    }
  }
];

const activas = $input.all()
  .filter(i => String(i.json.activa).toUpperCase() === 'SI')
  .map(i => ({ vacante: i.json.vacante, requisitos: i.json.requisitos }));
return activas.map(v => ({ json: v }));

const form = $input.first().json.body || $input.first().json;
const ok = form.vacante && form.requisitos &&
           form.vacante.trim() !== '' && form.requisitos.trim() !== '';
return [{ json: { ok: Boolean(ok), vacante: (form.vacante || '').trim(), requisitos: (form.requisitos || '').trim() } }];

const filas = $input.all();
const nueva = $('Validar Vacante').first().json;
const existe = filas.some(f => String(f.json.vacante).trim() === nueva.vacante);
return [{ json: { duplicado: existe, vacante: nueva.vacante, requisitos: nueva.requisitos } }];
